CREATE DATABASE IF NOT EXISTS `kominfo_kependudukan_new`;
USE `kominfo_kependudukan_new`;

DROP TABLE IF EXISTS `dispenduk_kepadatan`;
DROP TABLE IF EXISTS `bps_tpt`;
DROP TABLE IF EXISTS `bps_ipm`;
DROP TABLE IF EXISTS `bps_kemiskinan`;
DROP TABLE IF EXISTS `bps_kependudukan`;
DROP TABLE IF EXISTS `wilayah`;

CREATE TABLE `wilayah` (
  `kode_wilayah` varchar(10) NOT NULL,
  `nama_wilayah` varchar(100) NOT NULL,
  `tipe_wilayah` enum('Kabupaten','Kota') NOT NULL,
  PRIMARY KEY (`kode_wilayah`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `bps_kependudukan` (
  `kode_wilayah` varchar(10) NOT NULL,
  `jumlah_penduduk` double NOT NULL,
  `laju_pertumbuhan` double NOT NULL,
  `persentase_penduduk` double NOT NULL,
  `kepadatan_bps` double NOT NULL,
  `rasio_jenis_kelamin` double NOT NULL,
  `tahun` int(11) NOT NULL,
  PRIMARY KEY (`kode_wilayah`,`tahun`),
  CONSTRAINT `fk_pend_wilayah` FOREIGN KEY (`kode_wilayah`) REFERENCES `wilayah` (`kode_wilayah`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `bps_kemiskinan` (
  `kode_wilayah` varchar(10) NOT NULL,
  `jumlah_penduduk_miskin` double NOT NULL,
  `tahun` int(11) NOT NULL,
  PRIMARY KEY (`kode_wilayah`,`tahun`),
  CONSTRAINT `fk_miskin_wilayah` FOREIGN KEY (`kode_wilayah`) REFERENCES `wilayah` (`kode_wilayah`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `bps_ipm` (
  `kode_wilayah` varchar(10) NOT NULL,
  `ipm` double NOT NULL,
  `tahun` int(11) NOT NULL,
  PRIMARY KEY (`kode_wilayah`,`tahun`),
  CONSTRAINT `fk_ipm_wilayah` FOREIGN KEY (`kode_wilayah`) REFERENCES `wilayah` (`kode_wilayah`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `bps_tpt` (
  `kode_wilayah` varchar(10) NOT NULL,
  `tpt` double NOT NULL,
  `tahun` int(11) NOT NULL,
  PRIMARY KEY (`kode_wilayah`,`tahun`),
  CONSTRAINT `fk_tpt_wilayah` FOREIGN KEY (`kode_wilayah`) REFERENCES `wilayah` (`kode_wilayah`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `dispenduk_kepadatan` (
  `kode_wilayah` varchar(10) NOT NULL,
  `kepadatan` double NOT NULL,
  `semester` int(11) NOT NULL,
  `tahun` int(11) NOT NULL,
  PRIMARY KEY (`kode_wilayah`,`semester`,`tahun`),
  CONSTRAINT `fk_kepadatan_wilayah` FOREIGN KEY (`kode_wilayah`) REFERENCES `wilayah` (`kode_wilayah`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

